/* @lc app=leetcode id=3592 lang=kotlin */ class Solution { fun findCoins(numWays: IntArray): List<Int> = numWays.size.let { N -> (1..N).fold(LongArray(N + 1) { if (it == 0) 1L else 0L } to (listOf<Int>() as List<Int>?)) { (w, cs), i -> if (cs == null) w to null else if (w[i] == numWays[i - 1].toLong()) w to cs else if (numWays[i - 1].toLong() == w[i] + 1) w.copyOf().also { w2 -> (i..N).forEach { j -> w2[j] += w2[j - i] } } to cs + i else w to null }.second ?: listOf() } }